    function filterPlatformActivity(){
      const kind=document.getElementById("activityKindFilter")?.value||"",query=(document.getElementById("activitySearch")?.value||"").toLowerCase();
      document.querySelectorAll("#platformActivityEvents .activity-event-row").forEach(row=>row.hidden=(kind&&row.dataset.activityKind!==kind)||!row.textContent.toLowerCase().includes(query));
    }
