    function merchantTable(rows){return `<div class="table-scroll"><table><thead><tr><th>MERCHANT</th><th>OWNER</th><th>PLAN</th><th>SHIPMENTS MTD</th><th>STATUS</th><th></th></tr></thead><tbody id="merchantBody">${rows.map(m=>`<tr><td class="primary-cell">${escapeHtml(m.name)}<span class="subcell">${escapeHtml(m.id)} · ${escapeHtml(m.services)}</span></td><td>${escapeHtml(m.owner)}<span class="subcell">${escapeHtml(m.email)}</span></td><td>${escapeHtml(m.plan)}</td><td>${escapeHtml(m.shipments)}</td><td>${statusPill(m.status)}</td><td><button class="mini-button" data-merchant="${escapeHtml(m.id)}">Manage</button></td></tr>`).join("")}</tbody></table></div>`}
    function registrationTable(rows){return `<div class="table-scroll"><table><thead><tr><th>APPLICATION</th><th>BUSINESS OWNER</th><th>SERVICE</th><th>LOCATION</th><th>SUBMITTED</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody id="registrationBody">${rows.map(r=>`<tr><td class="primary-cell">${escapeHtml(r.business)}<span class="subcell">${escapeHtml(r.id)} · ${escapeHtml(r.email)}</span></td><td>${escapeHtml(r.owner)}<span class="subcell">${escapeHtml(r.phone)}</span></td><td>${escapeHtml(r.type)}</td><td>${escapeHtml(r.city)}</td><td>${escapeHtml(r.submitted)}</td><td>${statusPill(r.status)}</td><td>${r.status==="Pending review"?`<div class="row-actions"><button class="mini-button approve" data-review="${escapeHtml(r.id)}">Review</button></div>`:`<button class="mini-button" data-registration="${escapeHtml(r.id)}">Details</button>`}</td></tr>`).join("")}</tbody></table></div>`}
    function registrationPage(){return `<div class="page-heading"><div><p class="eyebrow">Merchant onboarding</p><h1>Merchant registrations</h1><p class="subtitle">Review business details and grant approved merchants access to the platform.</p></div><div class="heading-actions"><button class="button" data-action="exportRegistrations">${icon("download")} Export queue</button></div></div><div class="metrics">${metric("Awaiting review",String(registrations.filter(r=>r.status==="Pending review").length),"clipboard","needs decision","merchant applications")}${metric("Approved this month","38","check","↑ 12%","vs. last month")}${metric("Additional checks","3","alert","verification hold","compliance queue")}${metric("Average review","1.4 days","chart","within target","approval SLA")}</div><div class="callout" style="margin-bottom:12px">${icon("alert")} Merchant approval grants workspace access. Review business registration, authorized owner details, service scope, and settlement requirements before approving.</div><section class="panel table-panel"><div class="panel-heading"><div><h2 class="panel-title">Registration review queue</h2><p class="panel-subtitle">Pending and recently decided merchant applications</p></div><div class="table-tools"><input class="table-search" id="registrationSearch" placeholder="Search applications..." aria-label="Search applications"><select class="select-small" id="registrationFilter" aria-label="Filter application status"><option value="">All statuses</option><option>Pending review</option><option>Approved</option><option>Rejected</option><option>More information requested</option></select></div></div>${registrationTable(registrations)}<div class="table-footer"><span>Showing ${registrations.length} application records · sample data</span><div class="pagination"><button class="page-btn current">1</button><button class="page-btn">2</button><button class="page-btn">›</button></div></div></section>`}
    function merchantPage(){return `<div class="page-heading"><div><p class="eyebrow">Account governance</p><h1>Merchant accounts</h1><p class="subtitle">Manage e-commerce and Banking & Financial merchant accounts, service access, plans, and eligibility.</p></div><div class="heading-actions"><button class="button" data-action="exportMerchants">${icon("download")} Export</button><button class="button button-primary" data-action="inviteMerchant">${icon("plus")} Invite merchant</button></div></div><div class="metrics">${metric("Total accounts",String(merchants.length),"building","across merchant types","demo accounts")}${metric("Active",String(merchants.filter(m=>m.status==="Active").length),"check","eligible to ship","merchant accounts")}${metric("Under review",String(merchants.filter(m=>m.status==="Under review").length),"alert","risk follow-up","restricted actions")}${metric("Suspended",String(merchants.filter(m=>m.status==="Suspended").length),"shield","access disabled","awaiting review")}</div><section class="panel table-panel"><div class="panel-heading"><div><h2 class="panel-title">Merchant directory</h2><p class="panel-subtitle">Account type, lifecycle, and service entitlements</p></div><div class="table-tools"><input class="table-search" id="merchantSearch" placeholder="Search merchant or owner..." aria-label="Search merchants"><select id="merchantStatusFilter" class="select-small" aria-label="Filter merchant status"><option value="">All statuses</option><option>Active</option><option>Under review</option><option>Suspended</option></select></div></div><div class="table-scroll"><table><thead><tr><th>MERCHANT / ACCOUNT</th><th>PRIMARY OWNER</th><th>PLAN</th><th>SHIPMENTS MTD</th><th>JOINED</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody id="merchantBody">${merchants.map(m=>`<tr><td class="primary-cell">${escapeHtml(m.name)}<span class="subcell">${escapeHtml(m.id)} · ${escapeHtml(m.type||"E-commerce merchant")} · ${escapeHtml(m.services)}</span></td><td>${escapeHtml(m.owner)}<span class="subcell">${escapeHtml(m.email)}</span></td><td>${escapeHtml(m.plan)}</td><td>${escapeHtml(m.shipments)}</td><td>${escapeHtml(m.joined)}</td><td>${statusPill(m.status)}</td><td><button class="mini-button" data-merchant="${escapeHtml(m.id)}">Manage</button></td></tr>`).join("")}</tbody></table></div><div class="table-footer"><span>Showing ${merchants.length} merchant accounts</span><div class="pagination"><button class="page-btn current">1</button><button class="page-btn">2</button><button class="page-btn">›</button></div></section>`}
    function genericPage(page){const data=generic[page];if(page==="Plans & billing")return `<div class="page-heading"><div><p class="eyebrow">Commercial governance</p><h1>Plans & billing</h1><p class="subtitle">${data.desc}</p></div><button class="button button-primary" data-action="newPlan">${icon("plus")} Create plan</button></div><div class="metrics">${metric("Monthly platform revenue","৳ 1.84M","wallet","↑ 9.2%","this month")}${metric("Active subscriptions","292","building","4 service tiers","platform wide")}${metric("Past due","6","alert","৳ 42,600","needs follow-up")}${metric("Next settlement run","Oct 15","chart","daily cycle","finance schedule")}</div>${genericTable(page,data)}`;
      if(page==="Admin users")return `<div class="page-heading"><div><p class="eyebrow">Access governance</p><h1>Admin users & roles</h1><p class="subtitle">Control privileged access using role-based permissions and scoped administration.</p></div><button class="button button-primary" data-action="inviteAdmin">${icon("plus")} Invite administrator</button></div><div class="callout" style="margin-bottom:12px">${icon("shield")} Super admin actions are audited. Require MFA for elevated roles and grant only the permissions needed for each operational responsibility.</div><section class="panel table-panel"><div class="panel-heading"><div><h2 class="panel-title">Platform administrator directory</h2><p class="panel-subtitle">${adminUsers.length} administrators · MFA required for elevated access</p></div><input class="table-search" id="adminSearch" placeholder="Search administrator..." aria-label="Search administrators"></div><div class="table-scroll"><table><thead><tr><th>ADMINISTRATOR</th><th>ROLE</th><th>ACCESS SCOPE</th><th>STATUS</th><th>LAST SIGN-IN / ACTIVITY</th><th></th></tr></thead><tbody id="adminBody">${adminUsers.map((u,i)=>`<tr><td class="primary-cell">${escapeHtml(u[0])}<span class="subcell">${escapeHtml(u[1])}</span></td><td>${escapeHtml(u[2])}</td><td>${escapeHtml(u[3])}</td><td>${statusPill(u[4])}</td><td>${escapeHtml(u[5])}</td><td><button class="mini-button" data-admin="${i}">Manage</button></td></tr>`).join("")}</tbody></table></div></section><div class="setting-grid"><article class="setting-card"><strong>Super Administrator</strong><p>Full platform control, approvals, security, access policies, and billing governance.</p><span class="status status-bad">Privileged role · 2 users</span></article><article class="setting-card"><strong>Operations Administrator</strong><p>Courier network, riders, dispatch, hubs, and shipment exceptions.</p><span class="status status-blue">Scoped role · 4 users</span></article><article class="setting-card"><strong>Finance Administrator</strong><p>COD reconciliation, merchant settlements, invoices, and plan billing.</p><span class="status status-blue">Scoped role · 3 users</span></article><article class="setting-card"><strong>Merchant Support</strong><p>Merchant account support with restricted financial and security access.</p><span class="status status-blue">Scoped role · 5 users</span></article></div>`;
      if(page==="Platform settings")return `<div class="page-heading"><div><p class="eyebrow">Global configuration</p><h1>Platform settings</h1><p class="subtitle">Configure defaults shared across merchant workspaces and courier operations.</p></div><button class="button button-primary" data-action="saveSettings">Save changes</button></div><div class="callout" style="margin-bottom:12px">${icon("alert")} Global policy changes affect all merchants and operations users. Review the change scope before saving.</div><div class="setting-grid"><article class="setting-card"><strong>Merchant registration</strong><p>New merchant access requires review by an authorized administrator.</p><div class="setting-card-bottom"><span class="setting-value">Manual approval required</span><button class="toggle on" aria-label="Toggle merchant approval"></button></div></article><article class="setting-card"><strong>Identity & MFA</strong><p>Require multi-factor authentication for privileged platform roles.</p><div class="setting-card-bottom"><span class="setting-value">Enforced for admins</span><button class="toggle on" aria-label="Toggle admin MFA"></button></div></article><article class="setting-card"><strong>Merchant notifications</strong><p>Send registration, account, and service notifications by email.</p><div class="setting-card-bottom"><span class="setting-value">Email enabled</span><button class="toggle on" aria-label="Toggle email notifications"></button></div></article><article class="setting-card"><strong>Risk review threshold</strong><p>Flag merchant accounts for manual review when risk indicators exceed policy.</p><div class="setting-card-bottom"><span class="setting-value">Review threshold · 70</span><button class="button button-sm" data-toast="Risk review threshold editor opened.">Configure</button></div></article><article class="setting-card"><strong>Data retention</strong><p>Keep platform security and administrator audit records.</p><div class="setting-card-bottom"><span class="setting-value">Audit records · 365 days</span><button class="button button-sm" data-toast="Retention policy editor opened.">Configure</button></div></article><article class="setting-card"><strong>Default service availability</strong><p>Control which services can be requested during merchant onboarding.</p><div class="setting-card-bottom"><span class="setting-value">E-commerce · Domestic · Documents</span><button class="button button-sm" data-page-link="Service catalog">Manage services</button></div></article></div>`;
      if(page==="Import settings")return `<div class="page-heading"><div><p class="eyebrow">Platform control · Excel and CSV</p><h1>Spreadsheet imports</h1><p class="subtitle">Required columns, defaults, default destination and limits for the merchant and operations imports.</p></div></div><div class="callout" style="margin-bottom:12px" id="importSettingsPointer">${icon("box")} Services and prices: <button type="button" class="button button-sm" data-page-link="Service plans" style="margin-left:6px">Service plans</button></div>`;
      if(page==="Integrations")return `<div class="page-heading"><div><p class="eyebrow">Platform connections</p><h1>Integrations</h1><p class="subtitle">${data.desc}</p></div><button class="button button-primary" data-action="newIntegration">${icon("plus")} Add integration</button></div>${genericTable(page,data)}`;
      if(page==="Audit log")return `<div class="page-heading"><div><p class="eyebrow">Security & accountability</p><h1>Audit & security log</h1><p class="subtitle">${data.desc}</p></div><button class="button" data-action="exportAudit">${icon("download")} Export log</button></div><div class="metrics">${metric("Privileged actions","128","clipboard","this month","administrator activity")}${metric("MFA coverage","100%","shield","all admin accounts","security control")}${metric("Security alerts","3","alert","1 needs review","last 7 days")}${metric("Audit retention","365 days","settings","platform policy","log management")}</div>${genericTable(page,data)}`;
      return genericTable(page,data)}
    function genericTable(page,data){return `<section class="panel table-panel"><div class="panel-heading"><div><h2 class="panel-title">${escapeHtml(page)} register</h2><p class="panel-subtitle">Platform administration · sample records</p></div><input class="table-search" id="genericSearch" placeholder="Search ${escapeHtml(page.toLowerCase())}..." aria-label="Search ${escapeHtml(page)}"></div><div class="table-scroll"><table><thead><tr>${data.cols.map(c=>`<th>${escapeHtml(c.toUpperCase())}</th>`).join("")}</tr></thead><tbody id="genericBody">${data.rows.map((r,ri)=>`<tr>${r.map((cell,i)=>`<td>${i===r.length-1&&["Plans & billing","Integrations","Audit log"].includes(page)?statusPill(cell):page==="Import settings"&&i===3?statusPill(cell):page==="Import settings"&&i===4?`<button class="toggle ${cell==="Active"?"on":""}" aria-label="Toggle ${escapeHtml(r[0])}" data-toggle-service="${ri}"></button>`:escapeHtml(cell)}</td>`).join("")}</tr>`).join("")}</tbody></table></div><div class="table-footer"><span>Showing ${data.rows.length} sample records</span><div class="pagination"><button class="page-btn current">1</button><button class="page-btn">2</button><button class="page-btn">›</button></div></div></section>`}
    function showPage(page){document.getElementById("breadcrumbPage").textContent=page==="Overview"?"Overview":page==="Registrations"||page==="Approvals"?"Merchant approvals":page;document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.page===page||(page==="Approvals"&&b.dataset.page==="Registrations")));document.getElementById("sidebar").classList.remove("open");const root=document.getElementById("mainContent");root.innerHTML=page==="Overview"?overview():page==="Registrations"||page==="Approvals"?registrationPage():page==="Merchants"?merchantPage():page==="Platform activity"?platformActivityPage():genericPage(page);attachFilters()}
    function attachFilters(){const registrationSearch=document.getElementById("registrationSearch"),registrationFilter=document.getElementById("registrationFilter");const filterRegistrations=()=>document.querySelectorAll("#registrationBody tr").forEach(row=>row.hidden=(registrationSearch&&!row.textContent.toLowerCase().includes(registrationSearch.value.toLowerCase()))||(registrationFilter&&registrationFilter.value&&!row.textContent.includes(registrationFilter.value)));if(registrationSearch)registrationSearch.addEventListener("input",filterRegistrations);if(registrationFilter)registrationFilter.addEventListener("change",filterRegistrations);const merchantSearch=document.getElementById("merchantSearch"),merchantFilter=document.getElementById("merchantStatusFilter");const filterMerchants=()=>document.querySelectorAll("#merchantBody tr").forEach(row=>row.hidden=(merchantSearch&&!row.textContent.toLowerCase().includes(merchantSearch.value.toLowerCase()))||(merchantFilter&&merchantFilter.value&&!row.textContent.includes(merchantFilter.value)));if(merchantSearch)merchantSearch.addEventListener("input",filterMerchants);if(merchantFilter)merchantFilter.addEventListener("change",filterMerchants);for(const [id,body]of [["genericSearch","genericBody"],["adminSearch","adminBody"]]){const input=document.getElementById(id);if(input)input.addEventListener("input",()=>document.querySelectorAll(`#${body} tr`).forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(input.value.toLowerCase())))}const activitySearch=document.getElementById("activitySearch"),activityFilter=document.getElementById("activityKindFilter");if(activitySearch)activitySearch.addEventListener("input",filterPlatformActivity);if(activityFilter)activityFilter.addEventListener("change",filterPlatformActivity)}
    let modalState={};
    function openModal(type,id){modalState={type,id};const title=document.getElementById("modalTitle"),description=document.getElementById("modalDescription"),fields=document.getElementById("modalFields"),submit=document.getElementById("modalSubmit");
      if(type==="registration"){const r=registrations.find(x=>x.id===id);title.textContent=`Review ${r.business}`;description.textContent=`Application ${r.id} · verify submitted details and service requirements.`;submit.textContent="Approve merchant";fields.innerHTML=`<div class="field"><label>Business owner</label><input value="${escapeHtml(r.owner)}" readonly></div><div class="field"><label>Business type</label><input value="${escapeHtml(r.type)}" readonly></div><div class="field full"><label>Contact email</label><input value="${escapeHtml(r.email)}" readonly></div><div class="field"><label>Contact phone</label><input value="${escapeHtml(r.phone)}" readonly></div><div class="field"><label>Operating city</label><input value="${escapeHtml(r.city)}" readonly></div><div class="field full"><label>Initial service plan</label><select id="approvalPlan"><option ${r.plan==="Growth"?"selected":""}>Growth</option><option ${r.plan==="Business"?"selected":""}>Business</option><option ${r.plan==="Enterprise"?"selected":""}>Enterprise</option></select></div><div class="field full"><label>Review note</label><textarea id="reviewNote" placeholder="Optional internal approval note"></textarea></div><div class="field full"><div class="row-actions"><button type="button" class="button button-danger button-sm" data-modal-reject="${escapeHtml(r.id)}">Reject application</button><button type="button" class="button button-sm" data-modal-info="${escapeHtml(r.id)}">Request more information</button></div></div>`}
      else if(type==="merchant"){const m=merchants.find(x=>x.id===id);title.textContent=m.name;description.textContent=`${m.id} · account status, service entitlements, and plan oversight.`;submit.textContent="Save account changes";fields.innerHTML=`<div class="field"><label for="merchantStatus">Account status</label><select id="merchantStatus"><option ${m.status==="Active"?"selected":""}>Active</option><option ${m.status==="Under review"?"selected":""}>Under review</option><option ${m.status==="Suspended"?"selected":""}>Suspended</option></select></div><div class="field"><label for="merchantPlan">Service plan</label><select id="merchantPlan">${["Starter","Growth","Business","Enterprise","Enterprise Plus"].map(p=>`<option ${m.plan===p?"selected":""}>${p}</option>`).join("")}</select></div><div class="field full"><label>Primary owner · contact</label><input value="${escapeHtml(m.owner)} · ${escapeHtml(m.email)}" readonly></div><div class="field full"><label>Enabled services</label><input value="${escapeHtml(m.services)}" readonly></div><div class="field full"><label for="merchantNote">Internal account note</label><textarea id="merchantNote" placeholder="Reason for status or plan change"></textarea></div>`}
      else if(type==="inviteMerchant"){title.textContent="Invite a merchant";description.textContent="Send a registration link to a prospective merchant.";submit.textContent="Prepare invitation";fields.innerHTML=`<div class="field"><label for="inviteBusiness">Business name</label><input id="inviteBusiness" required placeholder="Registered business name"></div><div class="field"><label for="inviteOwner">Primary contact</label><input id="inviteOwner" required placeholder="Contact name"></div><div class="field full"><label for="inviteEmail">Business email</label><input id="inviteEmail" type="email" required placeholder="name@company.example"></div><div class="field"><label for="inviteType">Merchant service type</label><select id="inviteType"><option value="ECOMMERCE">E-commerce</option><option value="BANKING_FINANCIAL">Banking & Financial</option></select></div><div class="field"><label for="invitePlan">Suggested plan</label><select id="invitePlan"><option>Growth</option><option>Business</option><option>Enterprise</option></select></div>`}
      else if(type==="inviteAdmin"){title.textContent="Invite platform administrator";description.textContent="Create a scoped admin invitation; elevated access is audited.";submit.textContent="Prepare invitation";fields.innerHTML=`<div class="field full"><label for="adminName">Administrator name</label><input id="adminName" required placeholder="Full name"></div><div class="field full"><label for="adminEmail">Work email</label><input id="adminEmail" type="email" required placeholder="name@company.example"></div><div class="field"><label for="adminRole">Role</label><select id="adminRole"><option>Operations Administrator</option><option>Finance Administrator</option><option>Merchant Support</option><option>Hub Manager</option></select></div><div class="field"><label for="adminScope">Initial scope</label><select id="adminScope"><option>Dhaka North</option><option>Dhaka Central</option><option>Dhaka South</option><option>Finance & settlements</option><option>Merchant accounts</option></select></div>`}
      else if(type==="newPlan"){title.textContent="Create service plan";description.textContent="Configure a plan for future merchant subscriptions.";submit.textContent="Create plan";fields.innerHTML=`<div class="field full"><label for="planName">Plan name</label><input id="planName" required placeholder="Plan name"></div><div class="field"><label for="planFee">Monthly fee (৳)</label><input id="planFee" type="number" min="0" required placeholder="0"></div><div class="field"><label for="planCod">COD fee (%)</label><input id="planCod" type="number" min="0" step=".1" required placeholder="1.5"></div><div class="field full"><label for="planServices">Included services</label><select id="planServices"><option>E-commerce + COD</option><option>Domestic + documents</option><option>All service lines</option></select></div>`}
      else{title.textContent=type==="newService"?"Add service to catalog":"Add platform integration";description.textContent="Register a platform capability for administrator review.";submit.textContent=type==="newService"?"Add service":"Save integration";fields.innerHTML=`<div class="field full"><label for="entryName">${type==="newService"?"Service name":"Integration name"}</label><input id="entryName" required placeholder="${type==="newService"?"e.g. International document":"e.g. Payment gateway"}"></div><div class="field"><label for="entryCategory">Category</label><select id="entryCategory"><option>E-commerce</option><option>Domestic courier</option><option>Platform</option><option>Finance</option></select></div><div class="field"><label for="entryStatus">Status</label><select id="entryStatus"><option>Active</option><option>Pilot</option><option>Disabled</option></select></div>`}
      document.getElementById("modalBackdrop").classList.add("open")}
    function closeModal(){document.getElementById("modalBackdrop").classList.remove("open");modalState={}}
    function updateRegistration(id,status){const r=registrations.find(x=>x.id===id);if(r){r.status=status;if(status==="Approved"&&!merchants.some(m=>m.email===r.email)){const nextMerchantId=Math.max(10000,...merchants.map(m=>Number(m.id.replace("MER-",""))||0))+1;const serviceType=r.type.includes("Document")?"Document express":r.type.toLowerCase().includes("domestic")?"E-commerce · Domestic · Documents":"E-commerce · COD";merchants.unshift({id:`MER-${nextMerchantId}`,name:r.business,owner:r.owner,email:r.email,plan:document.getElementById("approvalPlan")?.value||r.plan||"Growth",services:serviceType,joined:"Oct 14, 2026",shipments:"0",status:"Active"})}}closeModal();updateApprovalCount();showPage("Registrations");showToast(`${r?r.business:"Application"}: ${status.toLowerCase()}${status==="Approved"?" · merchant account activated":""}.`)}
    function updateApprovalCount(){const count=registrations.filter(r=>r.status==="Pending review").length;document.getElementById("registrationCount").textContent=count;document.querySelector('[data-page="Approvals"] .nav-count').textContent=count}
    function exportCsv(name,headers,rows){const csv=[headers,...rows].map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(",")).join("\r\n");const link=document.createElement("a");link.href=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));link.download=`delivery-fast-${name}.csv`;link.click();URL.revokeObjectURL(link.href);showToast(`${name.replaceAll("-"," ")} exported as CSV.`)}
    function showToast(message){const toast=document.getElementById("toast");toast.textContent=message;toast.classList.add("show");clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove("show"),2500)}
    document.getElementById("navigation").addEventListener("click",e=>{const b=e.target.closest("[data-page]");if(b)showPage(b.dataset.page)});
    document.getElementById("mainContent").addEventListener("click",e=>{const nav=e.target.closest("[data-page-link]");if(nav){showPage(nav.dataset.pageLink);return}const toast=e.target.closest("[data-toast]");if(toast){showToast(toast.dataset.toast);return}const settingToggle=e.target.closest(".setting-card .toggle");if(settingToggle){settingToggle.classList.toggle("on");showToast(`${settingToggle.getAttribute("aria-label").replace("Toggle ","")} ${settingToggle.classList.contains("on")?"enabled":"disabled"} for this demo session.`);return}const review=e.target.closest("[data-review]");if(review){openModal("registration",review.dataset.review);return}const info=e.target.closest("[data-registration]");if(info){const r=registrations.find(x=>x.id===info.dataset.registration);showToast(`${r.id}: ${r.status} · ${r.business}`);return}const merchant=e.target.closest("[data-merchant]");if(merchant){openModal("merchant",merchant.dataset.merchant);return}const admin=e.target.closest("[data-admin]");if(admin){showToast(`${adminUsers[Number(admin.dataset.admin)][0]} · role access review opened.`);return}const toggle=e.target.closest("[data-toggle-service]");if(toggle){toggle.classList.toggle("on");serviceRows[Number(toggle.dataset.toggleService)][4]=toggle.classList.contains("on")?"Active":"Disabled";showToast(`${serviceRows[Number(toggle.dataset.toggleService)][0]} ${toggle.classList.contains("on")?"enabled":"disabled"}.`);return}const action=e.target.closest("[data-action]");if(action){const a=action.dataset.action;if(a==="inviteMerchant")openModal("inviteMerchant");else if(a==="inviteAdmin")openModal("inviteAdmin");else if(a==="newPlan")openModal("newPlan");else if(a==="newService"||a==="newIntegration")openModal(a);else if(a==="saveSettings")showToast("Platform settings saved.");else if(a==="exportRegistrations")exportCsv("registrations",["Application","Business","Owner","Email","Phone","Type","City","Submitted","Status"],registrations.map(r=>[r.id,r.business,r.owner,r.email,r.phone,r.type,r.city,r.submitted,r.status]));else if(a==="exportMerchants")exportCsv("merchants",["ID","Name","Owner","Email","Plan","Services","Joined","Shipments","Status"],merchants.map(m=>[m.id,m.name,m.owner,m.email,m.plan,m.services,m.joined,m.shipments,m.status]));else if(a==="exportAudit")exportCsv("audit-log",generic["Audit log"].cols,generic["Audit log"].rows)}})
    document.getElementById("mainContent").addEventListener("click",e=>{const decision=e.target.closest("[data-modal-reject],[data-modal-info]");if(decision){updateRegistration(decision.dataset.modalReject||decision.dataset.modalInfo,decision.hasAttribute("data-modal-reject")?"Rejected":"More information requested")}});
    document.getElementById("mainContent").addEventListener("input",e=>{if(e.target.id==="registrationSearch"){const q=e.target.value.toLowerCase();document.querySelectorAll("#registrationBody tr").forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))}if(e.target.id==="merchantSearch"){const q=e.target.value.toLowerCase();document.querySelectorAll("#merchantBody tr").forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))}});
    document.getElementById("globalSearch").addEventListener("keydown",e=>{if(e.key==="Enter"){const q=e.currentTarget.value.trim().toLowerCase();if(!q)return;const m=merchants.find(x=>x.name.toLowerCase().includes(q)||x.id.toLowerCase()===q||x.owner.toLowerCase().includes(q));if(m){showPage("Merchants");const input=document.getElementById("merchantSearch");input.value=q;input.dispatchEvent(new Event("input"));showToast(`${m.name} · ${m.status}`)}else showToast(`No sample merchant found for “${e.currentTarget.value.trim()}”.`)}});
    document.getElementById("notifications").addEventListener("click",()=>showToast(`${registrations.filter(r=>r.status==="Pending review").length} merchant applications await review.`));
    document.getElementById("workspace").addEventListener("click",()=>showToast("Platform administration · super admin workspace."));
    document.getElementById("mobileMenu").addEventListener("click",()=>document.getElementById("sidebar").classList.toggle("open"));
    document.getElementById("modalClose").addEventListener("click",closeModal);document.getElementById("modalCancel").addEventListener("click",closeModal);document.getElementById("modalBackdrop").addEventListener("click",e=>{if(e.target.id==="modalBackdrop")closeModal()});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal()});
    document.getElementById("modalForm").addEventListener("click",e=>{const reject=e.target.closest("[data-modal-reject],[data-modal-info]");if(reject){updateRegistration(reject.dataset.modalReject||reject.dataset.modalInfo,reject.hasAttribute("data-modal-reject")?"Rejected":"More information requested")}});
    document.getElementById("modalForm").addEventListener("submit",e=>{
      e.preventDefault();
      const type=modalState.type;
      if(type==="registration"){updateRegistration(modalState.id,"Approved");return}
      if(type==="merchant"){
        const merchant=merchants.find(m=>m.id===modalState.id);
        merchant.status=document.getElementById("merchantStatus").value;
        merchant.plan=document.getElementById("merchantPlan").value;
        closeModal();showPage("Merchants");showToast(`${merchant.name} account changes saved.`);return
      }
      if(type==="inviteMerchant"){
        const business=document.getElementById("inviteBusiness").value.trim(),owner=document.getElementById("inviteOwner").value.trim(),email=document.getElementById("inviteEmail").value.trim();
        const id=`REG-${Math.max(2084,...registrations.map(r=>Number(r.id.replace("REG-",""))||0))+1}`;
        registrations.unshift({id,business,owner,email,phone:"Pending contact verification",type:document.getElementById("inviteType").value,plan:document.getElementById("invitePlan").value,city:"Pending",submitted:"Just now",status:"Pending review"});
        closeModal();updateApprovalCount();showPage("Registrations");showToast(`Invitation prepared for ${business}; application added to review queue.`);return
      }
      if(type==="inviteAdmin"){
        const name=document.getElementById("adminName").value.trim(),email=document.getElementById("adminEmail").value.trim(),role=document.getElementById("adminRole").value,scope=document.getElementById("adminScope").value;
        adminUsers.unshift([name,email,role,scope,"Invited","Invitation prepared"]);
        closeModal();showPage("Admin users");showToast(`Administrator invitation prepared for ${name}. MFA will be required.`);return
      }
      if(type==="newPlan"){
        const name=document.getElementById("planName").value.trim(),fee=document.getElementById("planFee").value,cod=document.getElementById("planCod").value,services=document.getElementById("planServices").value;
        generic["Plans & billing"].rows.push([name,`৳ ${fee}`,`${cod}% COD`,services,"0","Active"]);
        closeModal();showPage("Plans & billing");showToast(`${name} plan configuration saved to this demo session.`);return
      }
      const name=document.getElementById("entryName").value.trim(),category=document.getElementById("entryCategory").value,status=document.getElementById("entryStatus").value;
      if(type==="newService")serviceRows.push([name,category,"New platform service","Enabled",status]);
      else generic.Integrations.rows.push([name,category,"Production","Just now","Platform admin",status]);
      closeModal();showPage(type==="newService"?"Import settings":"Integrations");showToast(`${name} added to the ${type==="newService"?"service catalog":"integration registry"} for review.`)
    });
    showPage("Overview");
